def l_corner(cells):
    rs = [r for r, c in cells]
    cs = [c for r, c in cells]
    for r in (min(rs), max(rs)):
        for c in (min(cs), max(cs)):
            if ({(y, c) for y in range(min(rs), max(rs)+1)} |
                {(r, x) for x in range(min(cs), max(cs)+1)}) == cells:
                return r, c
    return None

def transform(grid):
    out = [row[:] for row in grid]
    comps = components(grid)
    bg = max(range(10), key=lambda k: sum(v == k for row in grid for v in row))
    guides = [(len(cells), color, cells, l_corner(cells)) for color, cells in comps
              if color != bg and l_corner(cells) is not None]
    if not guides:
        return out
    _, paint, guide, (r0, c0) = max(guides, key=lambda x: x[0])
    # Select closest filled square beyond the horizontal arm and across its stem.
    targets = []
    for color, cells in comps:
        if color == bg or cells == guide:
            continue
        rs = [r for r, c in cells]
        cs = [c for r, c in cells]
        if min(rs) <= r0 or max(cs) >= c0:
            continue
        h, w = max(rs)-min(rs)+1, max(cs)-min(cs)+1
        if h == w and len(cells) == h*w:
            distance = min(abs(r-gr)+abs(c-gc) for r, c in cells for gr, gc in guide)
            targets.append((distance, cells))
    if targets:
        target = min(targets, key=lambda x: x[0])[1]
        for r, c in target:
            out[r][c] = paint
    return out

